-- SalesPulse view definitions

-- View: fact_sales
CREATE VIEW fact_sales AS WITH clean_orders AS (SELECT order_id, customer_id, order_status, TRY_CAST(order_purchase_timestamp AS TIMESTAMP) AS order_ts, TRY_CAST(order_delivered_customer_date AS TIMESTAMP) AS delivered_ts, TRY_CAST(order_estimated_delivery_date AS TIMESTAMP) AS estimated_ts FROM orders), clean_items AS (SELECT order_id, order_item_id, product_id, seller_id, TRY_CAST(price AS DOUBLE) AS item_revenue, TRY_CAST(freight_value AS DOUBLE) AS freight_value FROM order_items), clean_customers AS (SELECT customer_id, customer_unique_id, customer_city, customer_state FROM customers), clean_products AS (SELECT product_id, product_category_name FROM products)SELECT o.order_id, o.customer_id, c.customer_unique_id, c.customer_city, c.customer_state, o.order_status, o.order_ts, CAST(o.order_ts AS DATE) AS order_date, date_trunc('month', o.order_ts) AS order_month, i.order_item_id, i.product_id, i.seller_id, COALESCE(t.product_category_name_english, p.product_category_name, 'unknown') AS category, i.item_revenue, i.freight_value, (i.item_revenue + i.freight_value) AS item_total_value, date_diff('day', CAST(o.order_ts AS DATE), CAST(o.delivered_ts AS DATE)) AS delivery_days, CASE  WHEN ((o.delivered_ts > o.estimated_ts)) THEN (1) ELSE 0 END AS late_flag FROM clean_orders AS o LEFT JOIN clean_customers AS c ON ((o.customer_id = c.customer_id)) LEFT JOIN clean_items AS i ON ((o.order_id = i.order_id)) LEFT JOIN clean_products AS p ON ((i.product_id = p.product_id)) LEFT JOIN category_translation AS t ON ((p.product_category_name = t.product_category_name));

-- View: order_summary
CREATE VIEW order_summary AS SELECT order_id, max(customer_unique_id) AS customer_unique_id, max(customer_state) AS customer_state, max(order_status) AS order_status, min(order_date) AS order_date, sum(item_revenue) AS order_revenue, sum(freight_value) AS total_freight, count_star() AS item_count, max(delivery_days) AS delivery_days, max(late_flag) AS late_flag FROM fact_sales GROUP BY order_id;

